"""
logger.info("Info text")
logger.debug("Debug text")
logger.error("Error text")
logger.warning("Warning text")
logger.critical("Critical text")
"""
import datetime
import logging
import pytz

from pathlib import Path


logger = logging.getLogger(__name__)
# logger.setLevel(logging.DEBUG)


def setup_logger(log_dir_path):
    for h in logger.__dict__['handlers']:
        if h.__class__.__name__ == 'FileHandler':
            return
    log_dir = Path(log_dir_path)
    log_dir.mkdir(parents=True, exist_ok=True)
    log_filename = 'generate_config.log'
    log_filepath = log_dir / log_filename

    logger.setLevel(logging.DEBUG)

    class Formatter(logging.Formatter):

        @staticmethod
        def converter(timestamp):
            dt = datetime.datetime.fromtimestamp(timestamp)
            return dt.astimezone(pytz.UTC)

        def formatTime(self, record, datefmt=None):
            dt = self.converter(record.created)
            return dt.strftime(datefmt)

    formatter = Formatter('{asctime} {levelname:8s}| {message}', style='{', datefmt='%I:%M:%S')

    file_handler = logging.FileHandler(log_filepath, mode='w')

    file_handler.setLevel(logging.DEBUG)
    file_handler.setFormatter(formatter)

    stream_handler = logging.StreamHandler()
    stream_handler.setFormatter(formatter)
    stream_handler.setLevel(logging.INFO)

    logger.addHandler(file_handler)
    logger.addHandler(stream_handler)
    logger.info("Logs stored in: {}".format(log_filepath))
